WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/49.0/connection.js")}
{!REQUIRESCRIPT("/soap/ajax/49.0/apex.js")}

var recordId = '{!Message__c.Id}';

sforce.apex.execute(
    'PDFDownloadController',
    'getPDFDownloadLink',
    { recordId: recordId },
    function(result) {
        if (result) {
            window.open(result, '_blank');
        } else {
            alert('PDF not found or not generated yet.');
        }
    }
);
